-- GENERATED FILE, edit warehouse/tables.py and run scripts/gen_ddl.py
-- Databricks (Delta, Unity Catalog). Keys are documented in COMMENT, not enforced.
-- The catalog funnelstream must exist before running (CREATE CATALOG is deliberately not issued).
-- CREATE TABLE IF NOT EXISTS does not change an existing table: schema changes need an explicit ALTER or a drop.

CREATE SCHEMA IF NOT EXISTS funnelstream.gold;

CREATE SCHEMA IF NOT EXISTS funnelstream.silver;

CREATE TABLE IF NOT EXISTS funnelstream.gold.dim_customer (
    customer_key BIGINT GENERATED BY DEFAULT AS IDENTITY,
    customer_id STRING NOT NULL,
    country STRING,
    city STRING,
    district STRING,
    signup_date DATE,
    primary_device STRING,
    marketing_consent BOOLEAN,
    valid_from TIMESTAMP NOT NULL,
    valid_to TIMESTAMP NOT NULL,
    is_current BOOLEAN NOT NULL
)
USING DELTA
COMMENT 'keys: customer_key (documented, not enforced); SCD2 dimension, current row has valid_to = 9999-12-31 00:00:00 UTC; lookup: customer_id, is_current; tracked: city, district, primary_device';

